  .particulas { position:fixed; inset:0; pointer-events:none; z-index:0; overflow:hidden; }
  .particulas span { position:absolute; border-radius:50%; background:var(--azul-claro); opacity:.15; animation:flutuar 12s infinite ease-in-out; }
  .particulas span:nth-child(1){width:180px;height:180px;top:10%;left:8%;animation-delay:0s;}
  .particulas span:nth-child(2){width:100px;height:100px;top:60%;left:80%;background:var(--dourado);opacity:.1;animation-delay:2s;animation-duration:15s;}
  .particulas span:nth-child(3){width:140px;height:140px;top:75%;left:15%;animation-delay:4s;animation-duration:18s;}
  @keyframes flutuar { 0%,100%{transform:translate(0,0) scale(1);} 50%{transform:translate(30px,-40px) scale(1.1);} }
