  .vazio { color:var(--cinza); font-size:.85rem; padding:.8rem; text-align:center; border:1px dashed rgba(139,154,177,.2); border-radius:10px; }
  .legenda { display:flex; gap:1.5rem; margin-top:1.5rem; font-size:.75rem; color:var(--cinza); }
  .legenda span { display:flex; align-items:center; gap:.4rem; }
  .legenda .pt { width:10px; height:10px; border-radius:3px; }
</style>
</head>
<body>
  <div class="topo">
    <div class="logo"><div class="ic">📅</div><a class="voltar" href="/cliente">← Voltar aos serviços</a></div>
    <div class="usuario"><div class="nome"><%= usuario.nome %></div><form method="POST" action="/sair"><button type="submit" class="sair">Sair</button></form></div>
  </div>
  <div class="container">
    <div class="cabecalho"><h1><%= servico.nome %></h1><p>Duração: <%= servico.duracao_min %> minutos • Preço: R$ <%= Number(servico.preco).toFixed(2).replace('.',',') %></p></div>
    <% if (query && query.erro === 'ocupado') { %><div class="alerta">Este horário já foi agendado por outro cliente. Escolha outro.</div><% } %>
    <% if (query && query.erro === '1') { %><div class="alerta">Horário inválido. Verifique os horários cadastrados.</div><% } %>
    <% const dias = {}; %>
    <% for (const d in porDia) { dias[d] = porDia[d]; } %>
    <% const tem = Object.keys(porDia).length > 0; %>
    <% if (!tem) { %><div class="vazio">Nenhum horário cadastrado para este serviço nas próximas semanas.</div><% } else { %>
      <div class="dias">
        <% for (const dia in porDia) { %>
          <div class="dia"><div class="nome"><%= DIAS[parseInt(dia,10)] %></div><div class="horas">
            <% porDia[dia].forEach(h => { %>
              <div class="hora <%= h.estado !== 'livre' ? 'ocupado' : '' %>" data-dia="<%= dia %>" data-data="<%= h.data %>" data-hora="<%= h.hora %>" <%= h.estado !== 'livre' ? '' : 'onclick="sel(this)"' %>><%= h.hora %></div>
            <% }) %>
          </div></div>
        <% } %>
      </div>
      <div class="legenda"><span><div class="pt" style="background:var(--verde)"></div> Livre</span><span><div class="pt" style="background:var(--cinza)"></div> Ocupado</span></div>
      <form id="form-agendar" method="POST" action="/cliente/agendar/<%= servico.id %>" style="display:none;">
        <input type="hidden" name="data" id="f-data"><input type="hidden" name="hora" id="f-hora">
      </form>
    <% } %>
  </div>
  <script>
    function sel(el){
      document.querySelectorAll('.hora.sel').forEach(x=>x.classList.remove('sel'));
      el.classList.add('sel');
      document.getElementById('f-data').value = el.dataset.data;
      document.getElementById('f-hora').value = el.dataset.hora;
      const f = document.getElementById('form-agendar');
      f.style.display = 'block';
      if (confirm('Confirmar agendamento em ' + el.dataset.hora + ' do dia ' + el.dataset.data + '?')) f.submit();
    }
  </script>
</body>
</html>

